import React from "react";
import withNavigation from "../utils/withNavigation";
import LeftSlidebar from "./leftSlidebar";
import axiosInstance from "../configurations/instance";

class EventsList extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      events: [],
      selectedEvent: null,
      editEvent: null,
    };
  }

  componentDidMount() {
    axiosInstance
      .get("/event/all-events")
      .then((response) => {
        this.setState({ events: response.data });
      })
      .catch((error) => console.error("Ошибка при загрузке событий:", error));
  }

  handleView = (id) => {
    axiosInstance
      .get(`/event/${id}`)
      .then((response) => {
        this.setState({ selectedEvent: response.data, editEvent: null });
      })
      .catch((error) => console.error("Ошибка при загрузке события:", error));
  };

  handleEdit = (id) => {
    axiosInstance
      .get(`/event/${id}`)
      .then((response) => {
        this.setState({ editEvent: response.data, selectedEvent: null });
      })
      .catch((error) => console.error("Ошибка при загрузке события:", error));
  };

  handleDelete = (id) => {
    axiosInstance
      .delete(`/event/${id}`)
      .then(() => {
        this.setState((prevState) => ({
          events: prevState.events.filter((event) => event.eventId !== id),
          selectedEvent: null,
          editEvent: null,
        }));
      })
      .catch((error) => console.error("Ошибка при удалении события:", error));
  };

  getStatus = (eventDate) => {
    const now = new Date();
    const eventStart = new Date(eventDate);
    const diffInMs = now - eventStart;
    const diffInHours = diffInMs / (1000 * 60 * 60);

    if (diffInHours < 0) {
      return "В ожидании";
    } else if (diffInHours <= 12) {
      return "В процессе";
    } else {
      return "Завершено";
    }
  };

  getStatusClass = (status) => {
    if (status === "В ожидании") return "status-pending";
    if (status === "В процессе") return "status-active";
    if (status === "Завершено") return "status-completed";
    return "";
  };

  render() {
    const { events, selectedEvent, editEvent } = this.state;

    return (
      <div className="creating-page">
        <header className="main-header"></header>
        <div className="profile-page">
          <LeftSlidebar />
          <div className="content">
            <h1>Список событий</h1>
            <table className="event-table">
              <thead>
                <tr>
                  <th>№</th>
                  <th>Название</th>
                  <th>Дата проведения</th>
                  <th>Статус</th>
                  <th>Действия</th>
                </tr>
              </thead>
              <tbody>
                {events.map((event, index) => {
                  const status = this.getStatus(event.eventDate);
                  const statusClass = this.getStatusClass(status);

                  return (
                    <tr key={event.eventId}>
                      <td>{index + 1}</td>
                      <td>{event.eventName}</td>
                      <td>{new Date(event.eventDate).toLocaleDateString()}</td>
                      <td>
                        <span className={`status-badge ${statusClass}`}>
                          {status}
                        </span>
                      </td>
                      <td>
                        <button
                          className="check"
                          onClick={() => this.handleView(event.eventId)}
                        >
                          Просмотр
                        </button>
                        {status === "В ожидании" && (
                          <>
                            <button
                              className="change"
                              onClick={() => this.handleEdit(event.eventId)}
                            >
                              Изменить
                            </button>
                            <button
                              className="delete"
                              onClick={() => this.handleDelete(event.eventId)}
                            >
                              Удалить
                            </button>
                          </>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>

            {selectedEvent && (
              <div className="event-details">
                <h1>Детали события</h1>
                <div className="createForm">
                  <h3>Название мероприятия</h3>
                  <div>{selectedEvent.eventName}</div>

                  <h3>Тип мероприятия</h3>
                  <div>{selectedEvent.eventType}</div>

                  <h3>Дата проведения</h3>
                  <div>{new Date(selectedEvent.eventDate).toLocaleString()}</div>

                  <h3>Проверяющие</h3>
                  {selectedEvent.emailFields.map((email, index) => (
                    <div key={index}>{email}</div>
                  ))}

                  <h3>Участники</h3>
                  <table className="participant-table">
                    <thead>
                      <tr>
                        <th>№</th>
                        <th>ФИО</th>
                        <th>ИИН</th>
                        <th>Статус</th>
                      </tr>
                    </thead>
                    <tbody>
                      {selectedEvent.participants.map((participant, index) => (
                        <tr key={index}>
                          <td>{index + 1}</td>
                          <td>{participant.name}</td>
                          <td>{participant.iin}</td>
                          <td>
                            <span
                              className={`status-badge ${
                                participant.status === "Посетил"
                                  ? "status-came"
                                  : "status-not-came"
                              }`}
                            >
                              {participant.status || "Неизвестно"}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {editEvent && (
              <div className="createForm">
                <h1>Редактирование события</h1>
                <h3>Название мероприятия</h3>
                <input
                  type="text"
                  value={editEvent.eventName}
                  onChange={(e) =>
                    this.setState({
                      editEvent: {
                        ...editEvent,
                        eventName: e.target.value,
                      },
                    })
                  }
                />

                <h3>Тип мероприятия</h3>
                <select
                  value={editEvent.eventType}
                  onChange={(e) =>
                    this.setState({
                      editEvent: {
                        ...editEvent,
                        eventType: e.target.value,
                      },
                    })
                  }
                >
                  <option value="" disabled>
                    Выберите тип мероприятия
                  </option>
                  <option value="seminar">Семинар</option>
                  <option value="competition">Соревнования</option>
                  <option value="conference">Конференция</option>
                </select>

                <h3>Дата проведения</h3>
                <input
                  type="datetime-local"
                  value={new Date(editEvent.eventDate)
                    .toISOString()
                    .slice(0, 16)}
                  onChange={(e) =>
                    this.setState({
                      editEvent: {
                        ...editEvent,
                        eventDate: e.target.value,
                      },
                    })
                  }
                />
                <button
                  className="add-button"
                  onClick={() => console.log("Save changes")}
                >
                  Сохранить
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }
}

export default withNavigation(EventsList);
